function q({registerIndicator:V,sourceValues:I,nulls:U}){V({id:"oa-rvi",name:"Relative Volatility Index (RVI)",category:"Volatility",placement:"pane",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"stdevLength",type:"number",label:"StdDev Length",default:10,min:2,max:5e3,step:1,tooltip:"Lookback period for calculating the Standard Deviation of source prices."},{key:"rmaLength",type:"number",label:"RMA Length (Wilder's Smoothing)",default:14,min:1,max:5e3,step:1,tooltip:"Lookback period for smoothing Upward and Downward Standard Deviations."}],plots:[{key:"rvi",type:"line",title:"RVI",style:{color:"#ffeb3b",lineWidth:2}}],calc(v,d){const b=Math.max(2,Math.floor(Number(d.stdevLength)||10)),t=Math.max(1,Math.floor(Number(d.rmaLength)||14)),a=I(v,d.source??"close"),g=v.length,y=new Array(g).fill(NaN),N=new Array(b).fill(NaN);let n=0,o=0,m=0,p=0;const w=1e-10,L=1/t;let l=0,i=1,r=0,s=1;for(let e=0;e<g;e++){const c=N[n];Number.isFinite(c)&&(m-=c,p-=c*c,o-=1);const u=Number.isFinite(a[e])?a[e]:0;m+=u,p+=u*u,o+=1,N[n]=u,n=(n+1)%b;let f=0;o>1&&(f=Math.sqrt(Math.max(0,p/o-Math.pow(m/o,2))));const S=e>0?a[e-1]:NaN,k=a[e];let D=0,M=0;if(Number.isFinite(S)&&Number.isFinite(k)){const R=k-S;R>0?D=f:R<0&&(M=f)}l=(l*(t-1)+D)/t,i=(1-L)*i;const x=i>w?l/(1-i):l;r=(r*(t-1)+M)/t,s=(1-L)*s;const A=s>w?r/(1-s):r;let F=50;const h=x+A;h!==0&&Number.isFinite(h)&&(F=100*x/h),y[e]=F}return{rvi:U(y)}}})}export{q as default};
